use crate::wasi::clocks::wall_clock;

struct Node;

/// Convert days since 1970-01-01 to a (year, month, day) civil date.
/// Uses Howard Hinnant's days-from-civil inverse. The input is non-negative,
/// so the arithmetic can be done in unsigned integers.
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = doy - (153 * mp + 2) / 5 + 1; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 }; // [1, 12]
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    (y, m, d)
}

/// Format a Unix-epoch seconds value as a 10-character `YYYY-MM-DD` date.
fn format_date(seconds: u64) -> String {
    let (y, m, d) = civil_from_days(seconds / 86_400);
    // Keep the date exactly ten characters even for absurd clock readings.
    let (y, m, d) = if y > 9_999 { (9_999, 12, 31) } else { (y, m, d) };
    let s = format!("{:04}-{:02}-{:02}", y, m, d);
    if s.len() == 10 {
        s
    } else {
        String::from("1970-01-01")
    }
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        RunInfo {
            date: format_date(started),
            started,
        }
    }
}

export!(Node);
